import * as THREE from 'three';

// Surface detail for the UV-less city kit. Tileable data maps (R albedo factor, G roughness
// factor, B height; generated by assets/system-world/build_textures.py) are projected
// triplanar: world space for static geometry, object space for moving parts so detail never
// slides across them. The same injection darkens and glosses rain-wet surfaces (puddles in
// low areas of up-facing ground, dry under the pavilions) and lights window panes by time of
// day. Pane lighting is decorative, never telemetry. pow() bases are abs() so multisampled
// edges cannot produce NaN.
// puddle: [none above, full below] in mip-averaged height of the top map (~10% of asphalt,
// ~7% of pavers and slab tops); gravel roofs, cladding and foliage drain.
export const KINDS = {
  'city.road': {top: 'asphalt', side: 'concrete', albedo: .55, rough: .7, bump: .012, wet: 1, puddle: [.447, .442]},
  'city.stone': {top: 'pavers', side: 'concrete', albedo: .5, rough: .6, bump: .014, wet: 1, puddle: [.523, .516]},
  'city.graphite': {top: 'gravel', side: 'panels', albedo: .42, rough: .5, bump: .016, wet: .8, metalTop: .3},
  'city.titanium': {top: 'panels', side: 'panels', albedo: .2, rough: .45, bump: .006, wet: .6},
  'city.bronze': {top: 'panels', side: 'panels', albedo: .18, rough: .4, bump: .006, wet: .6},
  'city.ceramic': {top: 'concrete', side: 'concrete', albedo: .3, rough: .4, bump: .008, wet: .8, puddle: [.464, .460]},
  'city.leaf': {top: 'foliage', side: 'foliage', albedo: .7, rough: .3, bump: .03, wet: .5},
  ground: {top: 'pavers', side: 'concrete', albedo: .55, rough: .6, bump: .014, wet: 1, topScale: .5, puddle: [.523, .516]},
};
export const WINDOWS = new Set(['city.ivory', 'city.warm']);
const LEVELS = {low: 0, medium: 1, high: 2, ultra: 2};
const float = value => Number(value).toFixed(4);
const VERTEX_PARS = `varying vec3 vSwPos;varying vec3 vSwNrm;
#ifdef SW_WINDOWS
attribute float swSeed;varying float vSwSeed;
#endif`;
const VERTEX_MAIN = `
#ifdef USE_INSTANCING
mat4 swObject=instanceMatrix;
#else
mat4 swObject=mat4(1.0);
#endif
#ifdef SW_WORLD
swObject=modelMatrix*swObject;
#endif
vSwPos=(swObject*vec4(transformed,1.0)).xyz;vSwNrm=mat3(swObject)*objectNormal;
#ifdef SW_WINDOWS
vSwSeed=swSeed>1.5?2.0:fract(swSeed+dot(swObject[3].xyz,vec3(.0913,.0571,.0729)));
#endif`;
const FRAGMENT_PARS = `uniform float swWet;uniform float swRain;uniform float swTime;uniform vec4 swWindow;uniform vec2 swFade;uniform vec4 swShelter[3];uniform vec3 swSky;
varying vec3 vSwPos;varying vec3 vSwNrm;
#ifdef SW_WINDOWS
varying float vSwSeed;
#endif
#ifdef SW_SURFACE
uniform sampler2D swTop;uniform sampler2D swSide;uniform vec2 swScale;
float swHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
vec3 swPerturb(vec3 pos,vec3 n,vec2 dh,float face){vec3 sx=dFdx(pos),sy=dFdy(pos),r1=cross(sy,n),r2=cross(n,sx);float det=dot(sx,r1)*face;return normalize(abs(det)*n-sign(det)*(dh.x*r1+dh.y*r2));}
#endif`;
// Unit-length world metres: dFdx(position) and a metre-scaled height give scale-correct bump.
const FRAGMENT_SAMPLE = `
vec3 swN=normalize(vSwNrm);
#ifdef SW_SURFACE
vec3 swW=pow(abs(swN),vec3(4.0));swW/=max(swW.x+swW.y+swW.z,1e-4);
float swDetail=1.0-smoothstep(swFade.x,swFade.y,length(vViewPosition));
float swUp=clamp(swN.y,0.0,1.0),swDry=0.0;
#ifdef SW_WORLD
for(int i=0;i<3;i++){vec4 r=swShelter[i];swDry=max(swDry,step(r.x,vSwPos.x)*step(vSwPos.x,r.z)*step(r.y,vSwPos.z)*step(vSwPos.z,r.w)*step(vSwPos.y,3.6));}
#endif
float swWetness=swWet*SW_WETK*(0.35+0.65*swUp)*(1.0-swDry),swAlbedoF=1.0,swRoughF=1.0,swH=0.5,swPuddle=0.0;
#if SW_LEVEL>0
vec4 swS=texture2D(swTop,vSwPos.xz*swScale.x)*swW.y+texture2D(swSide,vSwPos.zy*swScale.y)*swW.x+texture2D(swSide,vSwPos.xy*swScale.y)*swW.z;
vec4 swM=texture2D(swTop,vSwPos.xz*swScale.x*0.125,4.0);
swAlbedoF=mix(1.0,swS.r*2.0,SW_ALBEDO*swDetail)*mix(1.0,swM.r*2.0,SW_ALBEDO*0.6);
swRoughF=mix(1.0,swS.g*2.0,SW_ROUGH);swH=swS.b;
swPuddle=swWet*SW_WETK*(1.0-swDry)*smoothstep(0.8,0.97,swUp)*smoothstep(SW_PUDDLE_DRY,SW_PUDDLE_FULL,swM.b);
if(swRain>0.0){
  vec2 swRp=vSwPos.xz*2.2,swCell=floor(swRp),swF=fract(swRp)-0.5,swO=(vec2(swHash(swCell+17.3),swHash(swCell+41.9))-0.5)*0.3;
  float swPhase=fract(swTime*0.8+swHash(swCell)),swR=length(swF-swO),swFront=swPhase*0.33;
  float swRing=sin((swR-swFront)*70.0)*smoothstep(swFront+0.07,swFront,swR)*smoothstep(swFront-0.16,swFront,swR)*(1.0-swPhase);
  swH=mix(swH,0.5+0.3*swRing*swRain*smoothstep(0.35,0.8,swPuddle),swPuddle);
}
#endif
#endif`;
const APPLY_ALBEDO = `
#ifdef SW_SURFACE
diffuseColor.rgb*=swAlbedoF*mix(1.0,0.56,swWetness)*mix(1.0,0.7,swPuddle);
#endif`;
const APPLY_ROUGHNESS = `
#ifdef SW_SURFACE
roughnessFactor=clamp(roughnessFactor*swRoughF,0.04,1.0);roughnessFactor=mix(roughnessFactor,roughnessFactor*0.6,swWetness);roughnessFactor=mix(roughnessFactor,0.04,swPuddle);
#endif`;
const APPLY_METALNESS = `
#ifdef SW_SURFACE
metalnessFactor*=mix(1.0,SW_METAL_TOP,swW.y);
#endif`;
const APPLY_NORMAL = `
#if SW_LEVEL>1
normal=swPerturb(-vViewPosition,normal,vec2(dFdx(swH),dFdy(swH))*SW_BUMP*swDetail,faceDirection);
#endif`;
// Panes (four-vertex components on vertical faces) switch individually; larger lit parts
// and horizontal fixtures only follow the day/night brightness.
const APPLY_EMISSIVE = `
#ifdef SW_SURFACE
float swFresnel=pow(1.0-clamp(dot(normal,normalize(vViewPosition)),0.0,1.0),5.0)*0.95+0.05;
totalEmissiveRadiance+=swSky*swFresnel*(swPuddle*0.6+swWetness*0.1);
#endif
#ifdef SW_WINDOWS
float swPane=(1.0-smoothstep(0.35,0.65,abs(swN.y)))*(1.0-step(1.5,vSwSeed));
totalEmissiveRadiance*=mix(swWindow.w,mix(swWindow.z,swWindow.y,step(vSwSeed,swWindow.x)),swPane);
#endif`;

// One seed per connected component: every window pane is its own four-vertex quad in the kit.
export function windowSeeds(geometry) {
  const position = geometry?.getAttribute('position');
  if (!position || geometry.getAttribute('swSeed')) return;
  const count = position.count, parent = new Int32Array(count), index = geometry.getIndex();
  for (let i = 0; i < count; i++) parent[i] = i;
  const find = i => { while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; } return i; };
  const vertex = i => index ? index.getX(i) : i, total = index ? index.count : count;
  for (let i = 0; i + 2 < total; i += 3) { const a = find(vertex(i)); parent[find(vertex(i + 1))] = a; parent[find(vertex(i + 2))] = a; }
  const size = new Map(), centre = new Map();
  for (let i = 0; i < count; i++) {
    const root = find(i), c = centre.get(root) || [0, 0, 0];
    size.set(root, (size.get(root) || 0) + 1); c[0] += position.getX(i); c[1] += position.getY(i); c[2] += position.getZ(i); centre.set(root, c);
  }
  const seeds = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const root = find(i), n = size.get(root), c = centre.get(root);
    if (n > 6) { seeds[i] = 2; continue; }
    const h = Math.sin(c[0] / n * 12.9898 + c[1] / n * 78.233 + c[2] / n * 37.719) * 43758.5453;
    seeds[i] = h - Math.floor(h);
  }
  geometry.setAttribute('swSeed', new THREE.BufferAttribute(seeds, 1));
}

export function createSurfaces(renderer, options = {}) {
  const controller = new AbortController(), patched = new Map(), textures = [];
  const placeholder = new THREE.DataTexture(new Uint8Array([128, 128, 128, 255]), 1, 1);
  placeholder.colorSpace = THREE.NoColorSpace; placeholder.needsUpdate = true;
  const slots = {}, tiles = {}, scales = {};
  for (const kind of Object.values(KINDS)) for (const id of [kind.top, kind.side]) slots[id] ||= { value: placeholder };
  for (const name of Object.keys(KINDS)) scales[name] = { value: new THREE.Vector2(1 / 4, 1 / 4) };
  const shelters = (options.shelters || []).slice(0, 3).map(r => new THREE.Vector4(...r));
  while (shelters.length < 3) shelters.push(new THREE.Vector4(1e6, 1e6, -1e6, -1e6));
  const shared = {
    swWet: { value: 0 }, swRain: { value: 0 }, swTime: { value: 0 }, swShelter: { value: shelters }, swSky: { value: new THREE.Color(0x08121e) },
    swWindow: { value: new THREE.Vector4(.8, 1, .06, 1) }, swFade: { value: new THREE.Vector2(35, 140) },
  };
  let level = 2, loading = null, disposed = false, bytes = 0, expected = 0, loaded = 0, failures = 0, raining = false;
  const maxAnisotropy = renderer.capabilities.getMaxAnisotropy();
  const anisotropy = () => level > 1 ? Math.min(8, maxAnisotropy) : Math.min(4, maxAnisotropy);
  function inject(shader, material) {
    const { kind, windows, space } = patched.get(material), config = KINDS[kind];
    Object.assign(shader.uniforms, shared);
    // GLSL ES rejects undefined macros in #if, so SW_LEVEL is always defined (0 without surface detail).
    const defines = ['#define SW_LEVEL ' + (config ? level : 0)];
    if (space === 'world') defines.push('#define SW_WORLD');
    if (windows) defines.push('#define SW_WINDOWS');
    if (config) {
      shader.uniforms.swTop = slots[config.top]; shader.uniforms.swSide = slots[config.side]; shader.uniforms.swScale = scales[kind];
      defines.push('#define SW_SURFACE', '#define SW_ALBEDO ' + float(config.albedo), '#define SW_ROUGH ' + float(config.rough),
        '#define SW_BUMP ' + float(config.bump), '#define SW_WETK ' + float(space === 'world' ? config.wet : config.wet * .5), '#define SW_METAL_TOP ' + float(config.metalTop ?? 1),
        '#define SW_PUDDLE_DRY ' + float(config.puddle?.[0] ?? -1), '#define SW_PUDDLE_FULL ' + float(config.puddle?.[1] ?? -2));
    }
    const head = defines.join('\n') + '\n';
    shader.vertexShader = head + shader.vertexShader.replace('#include <common>', '#include <common>\n' + VERTEX_PARS)
      .replace('#include <begin_vertex>', '#include <begin_vertex>' + VERTEX_MAIN);
    shader.fragmentShader = head + shader.fragmentShader.replace('#include <common>', '#include <common>\n' + FRAGMENT_PARS)
      .replace('#include <map_fragment>', '#include <map_fragment>' + FRAGMENT_SAMPLE)
      .replace('#include <color_fragment>', '#include <color_fragment>' + APPLY_ALBEDO)
      .replace('#include <roughnessmap_fragment>', '#include <roughnessmap_fragment>' + APPLY_ROUGHNESS)
      .replace('#include <metalnessmap_fragment>', '#include <metalnessmap_fragment>' + APPLY_METALNESS)
      .replace('#include <normal_fragment_maps>', '#include <normal_fragment_maps>' + APPLY_NORMAL)
      .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>' + APPLY_EMISSIVE);
  }
  // Materials are shared by name; patching is idempotent and survives LOD rebuilds.
  function apply(material, space = 'world', kindName = material?.name) {
    if (!material?.isMeshStandardMaterial || patched.has(material)) return;
    const kind = KINDS[kindName] ? kindName : '', windows = WINDOWS.has(material.name);
    if (!kind && !windows) return;
    patched.set(material, { kind, windows, space });
    material.addEventListener('dispose', () => patched.delete(material));
    material.onBeforeCompile = shader => inject(shader, material);
    material.customProgramCacheKey = () => ['sw', kind, windows, space, kind ? level : 0].join('|');
    material.needsUpdate = true;
  }
  function prepare(mesh, dynamic = false) {
    if (!mesh?.isMesh) return;
    for (const material of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) {
      apply(material, dynamic ? 'object' : 'world');
      if (WINDOWS.has(material?.name)) windowSeeds(mesh.geometry);
    }
  }
  const url = file => options.url?.(file);
  let manifest = null;
  // Each map loads independently: a failed one keeps its neutral placeholder and is retried on
  // the next quality change instead of discarding the others.
  async function texture(entry) {
    const reply = await fetch(url(entry.file), { signal: controller.signal });
    if (!reply.ok) throw Error('Surface texture unavailable');
    const blob = await reply.blob(); if (disposed) return;
    const bitmap = await createImageBitmap(blob, { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
    if (disposed) { bitmap.close?.(); return; }
    const map = new THREE.Texture(bitmap);
    map.wrapS = map.wrapT = THREE.RepeatWrapping; map.colorSpace = THREE.NoColorSpace; map.flipY = false;
    map.anisotropy = anisotropy(); map.needsUpdate = true;
    textures.push(map); slots[entry.id].value = map; loaded++; bytes += blob.size; options.onProgress?.(bytes, expected);
  }
  function load() {
    if (loading || disposed || !options.url) return loading;
    loading = (async () => {
      if (!manifest) {
        const response = await fetch(url('manifest.json'), { signal: controller.signal });
        if (!response.ok) throw Error('Surface manifest unavailable');
        manifest = await response.json();
        const entries = (manifest.textures || []).filter(entry => slots[entry.id] && /^[a-z-]+\.webp$/.test(entry.file) && entry.tile_metres > 0);
        manifest.entries = entries; expected = entries.reduce((sum, entry) => sum + (entry.bytes || 0), 0);
        for (const entry of entries) tiles[entry.id] = entry.tile_metres;
        for (const [name, config] of Object.entries(KINDS)) scales[name].value.set(1 / ((tiles[config.top] || 4) / (config.topScale || 1)), 1 / (tiles[config.side] || 4));
      }
      const missing = manifest.entries.filter(entry => slots[entry.id].value === placeholder);
      const results = await Promise.allSettled(missing.map(texture));
      failures += results.filter(r => r.status === 'rejected').length;
    })().catch(() => { failures++; }).finally(() => { loading = null; });
    return loading;
  }
  return {
    apply, prepare,
    setTier(tier) {
      const next = LEVELS[tier] ?? 2;
      if (next !== level) { level = next; for (const [material, entry] of patched) if (entry.kind) material.needsUpdate = true; }
      for (const texture of textures) if (texture.anisotropy !== anisotropy()) { texture.anisotropy = anisotropy(); texture.needsUpdate = true; }
      if (level > 0) void load();
    },
    // Decorative pane lighting: a few panes by day, most at night; overcast days light more.
    // Wet ground reflects the horizon colour (the fog) instead of the neutral room environment.
    setLighting(day, evening, overcast = 0, sky = null) {
      if (sky) shared.swSky.value.copy(sky).multiplyScalar(1.25);
      const night = 1 - day, dusk = THREE.MathUtils.smoothstep(night, .1, .9);
      shared.swWindow.value.set(Math.min(.9, .12 + .72 * dusk + .12 * overcast), .22 + night * .98 + Math.min(1, evening) * .1, .05, .55 + .45 * night);
    },
    setWeather(value) { raining = value === 'rain'; shared.swRain.value = raining ? 1 : 0; },
    // Wet surfaces follow the weather over tens of seconds; without motion they switch at once.
    update(dt, animated) {
      const target = raining ? 1 : 0, wet = shared.swWet.value;
      if (!animated) { shared.swWet.value = target; return; }
      const step = Math.min(.1, Math.max(0, dt));
      shared.swTime.value += step;
      shared.swWet.value = wet + (target - wet) * Math.min(1, step / (target > wet ? 14 : 70));
    },
    progress: () => ({ bytes, expected }),
    stats: () => ({ detail: level, textures: loaded, failures, bytes, materials: patched.size, wet: +shared.swWet.value.toFixed(2), windows: +shared.swWindow.value.x.toFixed(2) }),
    dispose() {
      disposed = true; controller.abort();
      for (const texture of textures) { texture.dispose(); texture.source.data?.close?.(); }
      textures.length = 0; placeholder.dispose();
    },
  };
}
